"""Share of the total level per reading."""
from readings import load_readings


def level_shares(readings):
    """Return each reading's share of the total level, in order."""
    total = sum(x.level for x in readings)
    return [x.level / total for x in readings]


def stored_shares():
    """Shares for the stored readings."""
    return level_shares(load_readings())


def top_share(readings):
    """Return the largest share, or 0.0 when there are no readings."""
    shares = level_shares(readings)
    return max(shares) if shares else 0.0


def sensor_names(readings):
    """Return the distinct sensor values, in first-seen order."""
    names = []
    for x in readings:
        if x.sensor not in names:
            names.append(x.sensor)
    return names

