from readings import load_readings, ROWS
from breakdown import level_shares, stored_shares, top_share

TOTAL = sum(v for _, v in ROWS)


def test_stored_shares():
    shares = stored_shares()
    assert len(shares) == len(ROWS) and abs(sum(shares) - 1.0) < 1e-9


def test_generator_values():
    shares = level_shares(load_readings())
    assert abs(shares[0] - ROWS[0][1] / TOTAL) < 1e-9 and abs(shares[-1] - ROWS[-1][1] / TOTAL) < 1e-9


def test_list_input():
    shares = level_shares(list(load_readings()))
    assert abs(shares[1] - ROWS[1][1] / TOTAL) < 1e-9


def test_top_share_generator():
    assert abs(top_share(load_readings()) - max(v for _, v in ROWS) / TOTAL) < 1e-9


def test_empty():
    assert level_shares(iter([])) == [] and top_share(iter([])) == 0.0
